#include "zari/preview.hpp"
#include <fstream>
#include <sstream>
namespace zari {
Preview make_preview(const FileEntry&e,const PreviewConfig&c,int width,int height){Preview p;p.title=e.name;if(height<=0)return p;if(e.kind==FileKind::directory){ManagerConfig mc;mc.show_hidden=true;auto r=list_directory(e.path,mc);std::size_t dirs=0,files=0;std::uintmax_t size=0;for(const auto&x:r.entries){if(x.kind==FileKind::directory)++dirs;else{++files;size+=x.size;}}p.lines={std::to_string(dirs)+" directories, "+std::to_string(files)+" files", "Approximate visible size: "+human_size(size),""};for(const auto&x:r.entries){if(static_cast<int>(p.lines.size())>=height)break;p.lines.push_back((x.kind==FileKind::directory?"d ":"  ")+x.name);}return p;}if(e.kind!=FileKind::regular&&e.kind!=FileKind::executable){p.lines={"Type: special file","Path: "+e.path.string(),"Permissions: "+permission_string(e.permissions)};if(e.symlink_target)p.lines.push_back("Target: "+e.symlink_target->string());return p;}if(e.size>c.max_file_size){p.lines={"File is too large to preview",human_size(e.size)};return p;}std::ifstream f(e.path,std::ios::binary);if(!f){p.lines={"Cannot read file"};return p;}std::string sample(4096,'\0');f.read(sample.data(),sample.size());sample.resize(static_cast<std::size_t>(f.gcount()));if(sample.find('\0')!=std::string::npos){p.lines={"Binary file",human_size(e.size),"Path: "+e.path.string()};return p;}f.clear();f.seekg(0);std::string line;int n=1;while(std::getline(f,line)&&static_cast<int>(p.lines.size())<height){std::string expanded;for(char ch:line){if(ch=='\t')expanded+=std::string(c.tab_size-(expanded.size()%c.tab_size),' ');else expanded+=ch;}if(c.line_numbers)expanded=std::to_string(n)+"  "+expanded;if(width>0&&static_cast<int>(expanded.size())>width)expanded.resize(width);p.lines.push_back(std::move(expanded));++n;}return p;}
}
